INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 60000, 1, 190804, "カリン", "", 1, 0, 0, 1, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 60000, 2, 0, "", "", 0, 0, 1, 2, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60000, 2, 0, "", "", 0, 0, 1, 3, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 60000, 2, 0, "", "", 0, 0, 1, 4, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 60000, 2, 0, "", "", 0, 0, 2, 5, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 60000, 2, 0, "", "", 0, 0, 2, 6, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 60000, 2, 0, "", "", 0, 0, 2, 7, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 60000, 2, 0, "", "", 0, 0, 3, 8, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 60000, 2, 0, "", "", 0, 0, 3, 9, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60000, 2, 0, "", "", 0, 0, 3, 10, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60000, 2, 0, "", "", 0, 0, 3, 11, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 60000, 2, 0, "", "", 0, 0, 3, 12, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 60000, 2, 0, "", "", 0, 0, 4, 13, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 60000, 2, 0, "", "", 0, 0, 4, 14, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 60000, 2, 0, "", "", 0, 0, 4, 15, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 60000, 2, 0, "", "", 0, 0, 4, 16, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 60000, 2, 0, "", "", 0, 0, 4, 17, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 60000, 3, 190804, "カリン", "", 2, 0, 0, 18, 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 60000, 3, 190804, "カリン", "", 3, 0, 0, 19, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キミと出会ってもう\n1年もたつんだね！\nう～ん、いつも\n寝てばっかりだから、", 80001, 0, 101201, "ハツネ", "", 1, 0, 0, 20, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("少しでも\n寝る時間を減らして\nキミと一緒にいる\n時間増やしたいなぁ♪", 80001, 0, 101201, "ハツネ", "", 2, 0, 0, 21, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと知り合ってから\nもう1年…\n時がたつのは\n早いですね", 80001, 1, 103801, "シオリ", "", 1, 0, 0, 22, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("来年も、\n一緒にいられたら…\nうれしいな", 80001, 1, 103801, "シオリ", "", 2, 0, 0, 23, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと一緒にいるようになって、\nもう1年ですか…", 80001, 0, 103601, "キョウカ", "", 1, 0, 0, 24, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("最初の頃よりも、頼もしく\nなりましたね。私はどうですか？\n成長していますか？", 80001, 0, 103601, "キョウカ", "", 2, 0, 0, 25, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おにいちゃんとあってから、\n1年たったよ～！", 80001, 1, 102001, "ミミ", "", 1, 0, 0, 26, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ミミね、おにいちゃんと\nいっぱい遊べてたのしかったな～♪\nこれからもずっと\nいっしょにいてね～！", 80001, 1, 102001, "ミミ", "", 2, 0, 0, 27, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("にいちゃんがミソギのイタズラに\n引っかかり続けてもう1年かぁ", 80001, 2, 100401, "ミソギ", "", 1, 0, 0, 28, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…これからもいっぱいミソギと\n遊んでね、にいちゃん！", 80001, 2, 100401, "ミソギ", "", 2, 0, 0, 29, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう王子はんと会うてから\n1年ぐらいたつそうどすえ\n早いもんやなあ", 80001, 0, 101001, "マホ", "", 1, 0, 0, 30, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("このままやと、\nうちもあっという間に\n干からびてしまいそうどすえ\nなーんてな。うふふ", 80001, 0, 101001, "マホ", "", 2, 0, 0, 31, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お主と会って早1年じゃな\nこれからも存分に尽くすがよい", 80001, 1, 104401, "イリヤ", "", 1, 0, 0, 32, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わらわもたまには、お主の献身に\n報いてやらぬでもない♪", 80001, 1, 104401, "イリヤ", "", 2, 0, 0, 33, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう、キミと出会って結構な時間が\nたつさ～。でも、私たちの旅は\nまだまだ始まったばかりさ～！", 80001, 2, 101701, "カオリ", "", 1, 0, 0, 34, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも、どうぞよろしく\nお願いするさ～！", 80001, 2, 101701, "カオリ", "", 2, 0, 0, 35, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あんたと出会ってからもうそんなに\nたつのね～", 80001, 0, 102801, "サレン", "", 1, 0, 0, 36, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あっという間だったって感じるほど\n楽しかったわ！\nこれからも一緒に頑張りましょ！", 80001, 0, 102801, "サレン", "", 2, 0, 0, 37, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("出会ってから1年間、ずっと\nご迷惑をかけっぱなしで、\nすみません…", 80001, 1, 102501, "スズメ", "", 1, 0, 0, 38, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからはもっと頑張りますから\n見ていてくださいね\nできれば…\n今までよりも、私の近くで♪", 80001, 1, 102501, "スズメ", "", 2, 0, 0, 39, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("振り返れば、今までいろんなことが\nあったにゃあ…", 80001, 0, 104601, "タマキ", "", 1, 0, 0, 40, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも、二人でたくさんの\n思い出をがっぽり作っていく\nにゃー！", 80001, 0, 104601, "タマキ", "", 2, 0, 0, 41, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キミとの師弟関係も、\nもう1年なのね…\nでもキミに教えることは、", 80001, 1, 104801, "ミフユ", "", 1, 0, 0, 42, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まだまだいっぱいあるわ\nこれからも、\nしっかりついて来てね！", 80001, 1, 104801, "ミフユ", "", 2, 0, 0, 43, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたさまと出会ってもう1年…", 80001, 0, 103201, "アキノ", "", 1, 0, 0, 44, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("光陰矢のごとし、とはまさに\nこのことですわ。…思い出は決して\nお金では買えませんわね", 80001, 0, 103201, "アキノ", "", 2, 0, 0, 45, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ダメな私を1年間も見捨てないで\nくれて、本当にありがとう", 80001, 1, 103401, "ユカリ", "", 1, 0, 0, 46, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("情けないところいっぱいみせるかも\nしれないけど、これからも一緒に\nいてくれると、うれしいな", 80001, 1, 103401, "ユカリ", "", 2, 0, 0, 47, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オマエと出会ってもう1年か\nまさかこのワタシの結婚相手に\nなろうとはな…", 80001, 0, 107101, "クリスティーナ", "", 1, 0, 0, 48, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ともかくこれからも\n愉しませてくれよ☆", 80001, 0, 107101, "クリスティーナ", "", 2, 0, 0, 49, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("君と出会ってからもう1年か。\n以前と比べて私の表情もいくらか\n柔らかくなった気がするんだが、\nどうだろう？", 80001, 1, 104701, "ジュン", "", 1, 0, 0, 50, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("見えないから分からないって？\nそれもそうだな…", 80001, 1, 104701, "ジュン", "", 2, 0, 0, 51, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう1年たったみたいだね\nあなたをからかってばかりだった\nけど、楽しかった♪", 80001, 0, 103701, "トモ", "", 1, 0, 0, 52, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからもよろしくね！", 80001, 0, 103701, "トモ", "", 2, 0, 0, 53, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("出会って、もう1年たっちゃった\nんスね。なんだか意外ッス", 80001, 1, 100501, "マツリ", "", 1, 0, 0, 54, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("毎日楽しくて、あっという間に過ぎ\nちゃったみたいなんスよね\nこれからも一緒に悪と戦うッス！", 80001, 1, 100501, "マツリ", "", 2, 0, 0, 55, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オマエと会って1年なの！\n全然成仏もできなかったし、", 80001, 0, 100701, "ミヤコ", "", 1, 0, 0, 56, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("生き返りもしなかったけど、\nすごく楽しかったの～♪\nオマエとプリンがあれば、\nミヤコはハッピーなの～♪", 80001, 0, 100701, "ミヤコ", "", 2, 0, 0, 57, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと出会って1年なんですね\nでも、私の占いでは、私とあなたは", 80001, 1, 103101, "シノブ", "", 1, 0, 0, 58, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("来年も再来年も一緒にいるようです\nふふ、よろしくお願いしますね", 80001, 1, 103101, "シノブ", "", 2, 0, 0, 59, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("貴様が閃光のシグルドとして覚醒し\nもう1年か…。これからも我らの\n長き戦いに終わりはないが、", 80001, 0, 100901, "アンナ", "", 1, 0, 0, 60, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでも貴様となら…\n添い遂げる覚悟はできているぞ！", 80001, 0, 100901, "アンナ", "", 2, 0, 0, 61, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("君と出会ってもう1年だって！\n早いねー！", 80001, 1, 101301, "ナナカ", "", 1, 0, 0, 62, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも最強のバディタッグで\n大活躍だー！\n頼りにしてるよ、相棒！", 80001, 1, 101301, "ナナカ", "", 2, 0, 0, 63, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("1年たつのって、あっという間ね\nまだまだ君の知らない部分が\nたくさんあるし…", 80001, 0, 105101, "ミツキ", "", 1, 0, 0, 64, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも、いろんなところを\n調べさせてね？", 80001, 0, 105101, "ミツキ", "", 2, 0, 0, 65, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お前さんと出会ってもう1年か\n助太刀するつもりが", 80001, 1, 105601, "ルカ", "", 1, 0, 0, 66, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("逆に助けられたりもしたね\nこれからもよろしく頼むよ！", 80001, 1, 105601, "ルカ", "", 2, 0, 0, 67, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("早いものですわね、あなた様と\nお会いして、もう1年…", 80001, 2, 102701, "エリコ", "", 1, 0, 0, 68, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなた様といると、時があっと\nいう間に過ぎてしまいます\n時間を止める研究をしなくては\nいけませんね…", 80001, 2, 102701, "エリコ", "", 2, 0, 0, 69, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お兄ちゃんと会ってから、もう、\n1年なんだね。私、少しは\nお姉ちゃんっぽくなったかな？", 80001, 0, 102301, "アヤネ", "", 1, 0, 0, 70, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、ぷうきちもお兄ちゃんっぽく\nなったよね？", 80001, 0, 102301, "アヤネ", "", 2, 0, 0, 71, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと出会って、\nもう1年がたったんですね…\nこれからもそばにいて、", 80001, 1, 104201, "チカ", "", 1, 0, 0, 72, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("私のことを見守ってください\nできることなら、ずっと…", 80001, 1, 104201, "チカ", "", 2, 0, 0, 73, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お兄ちゃんと出会って1年かぁ\n私、相変わらずダメダメで…", 80001, 2, 102101, "クルミ", "", 1, 0, 0, 74, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("で、でもこれからもずっと…\n一緒にいたいなぁ…", 80001, 2, 102101, "クルミ", "", 2, 0, 0, 75, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("再会してちょうど1年だね\nお祝いにごちそう作ってきたよ～♪\n特製ケーキと、お寿司と、", 80001, 0, 104901, "シズル", "", 1, 0, 0, 76, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ハンバーグと、カレーと、\nシチューと、あ、隠しきれない隠し\n味は、お姉ちゃんの愛情だよ！", 80001, 0, 104901, "シズル", "", 2, 0, 0, 77, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お兄ちゃんと再会して、もう1年\nなんですね。\n会えなかった時を思うと、", 80001, 1, 101101, "リノ", "", 1, 0, 0, 78, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("信じられないくらい幸せな1年\nでした！もう絶対、私から離れ\nないでくださいね♪", 80001, 1, 101101, "リノ", "", 2, 0, 0, 79, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("騎士クンと出会ってから今まで、\nいろんなことがあったよね\n楽しいこと、ドキドキしたこと…", 80001, 0, 100201, "ユイ", "", 1, 0, 0, 80, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんな日々をこれからも、\nず、ずっと一緒に…\n過ごしていきたいな…！", 80001, 0, 100201, "ユイ", "", 2, 0, 0, 81, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("騎士くんと出会って、まだ1年しか\nたってないんだ！？", 80001, 1, 100101, "ヒヨリ", "", 1, 0, 0, 82, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なんかもうずっと一緒にいる気が\nするなぁ…えへへ。これからの\n1年もまたよろしくねっ！\n騎士くん！", 80001, 1, 100101, "ヒヨリ", "", 2, 0, 0, 83, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("初めてキミに出会って1年…\n随分見違えたね私もキミも、\n更に強くなっていく…", 80001, 2, 100301, "レイ", "", 1, 0, 0, 84, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キミに背中を預けられる日が、\n早くきますように", 80001, 2, 100301, "レイ", "", 2, 0, 0, 85, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("1年もわたしのことを、忘れない\nでいてくれて、ありがとうござい\nます！", 80001, 0, 105801, "ペコリーヌ", "", 1, 0, 0, 86, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからもずっと、覚えていて\nくださいね！", 80001, 0, 105801, "ペコリーヌ", "", 2, 0, 0, 87, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こうして1年も、主さまのおそばに\n置いていただけて、とても光栄\nです。どうかこれからも、", 80001, 1, 105901, "コッコロ", "", 1, 0, 0, 88, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("末永く主さまをお世話させて\nください。わたくしは、ずっと\n主さまのガイド役でいたいのです", 80001, 1, 105901, "コッコロ", "", 2, 0, 0, 89, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("1年か、まっさかこんなに長い\n付き合いになるなんてね～\nでも…わりと楽しい1年だったかも", 80001, 2, 106001, "キャル", "", 1, 0, 0, 90, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だから、もうしばらくあんたに\n付き合ってやるわよ喜びなさい！", 80001, 2, 106001, "キャル", "", 2, 0, 0, 91, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新しい年のはじめに、\nおみくじはいかがでしょうか？\nよい運勢であるほど、\n沢山プレゼントが貰えますよ♪", 60001, 1, 112101, "スズメ", "", 1, 0, 0, 92, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", 60001, 2, 0, "", "", 0, 0, 1, 93, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60001, 2, 0, "", "", 0, 0, 1, 94, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 60001, 2, 0, "", "", 0, 0, 1, 95, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 60001, 2, 0, "", "", 0, 0, 1, 96, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", 60001, 2, 0, "", "", 0, 0, 1, 97, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", 60001, 2, 0, "", "", 0, 0, 2, 98, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", 60001, 2, 0, "", "", 0, 0, 2, 99, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 60001, 2, 0, "", "", 0, 0, 2, 100, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 60001, 2, 0, "", "", 0, 0, 2, 101, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", 60001, 2, 0, "", "", 0, 0, 2, 102, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", 60001, 2, 0, "", "", 0, 0, 3, 103, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", 60001, 2, 0, "", "", 0, 0, 3, 104, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60001, 2, 0, "", "", 0, 0, 3, 105, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60001, 2, 0, "", "", 0, 0, 3, 106, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", 60001, 2, 0, "", "", 0, 0, 3, 107, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", 60001, 2, 0, "", "", 0, 0, 3, 108, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", 60001, 2, 0, "", "", 0, 0, 3, 109, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", 60001, 2, 0, "", "", 0, 0, 4, 110, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", 60001, 2, 0, "", "", 0, 0, 4, 111, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", 60001, 2, 0, "", "", 0, 0, 4, 112, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 60001, 2, 0, "", "", 0, 0, 4, 113, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 60001, 2, 0, "", "", 0, 0, 4, 114, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", 60001, 2, 0, "", "", 0, 0, 4, 115, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 60001, 2, 0, "", "", 0, 0, 4, 116, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はいかがでしたか？\n新たに始まる一日が、\nあなたにとってよい日になりますように\n明日もお待ちしていますね♪", 60001, 3, 112101, "スズメ", "", 2, 0, 0, 117, 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじ、楽しんで頂けましたか？\nあなたの新しい年が\n素晴らしいものになるよう、\n心からお祈りしますね", 60001, 3, 112101, "スズメ", "", 3, 0, 0, 118, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ヒューヒュー♪\nドンドンパフパフー♪", 80003, 0, 105801, "ペコリーヌ", "", 1, 0, 0, 119, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ひゅーひゅー\nどんどんぱふぱふー\nでございます", 80003, 1, 105901, "コッコロ", "", 1, 0, 0, 120, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さぁ、キャルさまもご一緒に\nどんどんぱふぱふいたしましょう", 80003, 1, 105901, "コッコロ", "", 2, 0, 0, 121, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え？　ちょっと\nいきなりなにっ？", 80003, 2, 106001, "キャル", "", 1, 0, 0, 122, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ドンドンパフパフってなんなの？\nあたしにも分かるように\nちゃんと説明しなさいっての！", 80003, 2, 106001, "キャル", "", 2, 0, 0, 123, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("実はですねキャルちゃん！\nもうすぐわたしたちにとっての\n大切な節目──", 80003, 0, 105801, "ペコリーヌ", "", 2, 0, 0, 124, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("『プリンセスコネクト！\nRe:Dive』\n2.5周年なんですよ！\nやばいですね☆", 80003, 0, 105801, "ペコリーヌ", "", 3, 0, 0, 125, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですからその日に向けて\n今から気分を盛り上げているのです", 80003, 1, 105901, "コッコロ", "", 3, 0, 0, 126, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ああ、そういえば\nそんな時期だっけ\nって言っても、もう少し先じゃない\n気が早いんじゃないの？", 80003, 2, 106001, "キャル", "", 3, 0, 0, 127, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いいえ、キャルさま\nこういったお祝いは準備から\n楽しむものでございます\nそうですよね、ペコリーヌさま", 80003, 1, 105901, "コッコロ", "", 4, 0, 0, 128, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("その通りです♪　というわけで！\nカウントダウンの始まりですよ！\nみんなで一緒に2.5周年に向けて\n盛り上がっていきましょー☆", 80003, 0, 105801, "ペコリーヌ", "", 4, 0, 0, 129, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ド、ドンドンパフパフ～\nって何言わせんのよ！\nまったくもう、浮かれちゃってさ", 80003, 2, 106001, "キャル", "", 4, 0, 0, 130, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。キャルさまもワクワクして\nおいでのようですね\nそれでは主さま。大切な記念日まで\nどうぞご期待くださいませ", 80003, 1, 105901, "コッコロ", "", 5, 0, 0, 131, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("記念日を盛り上げるったって\n一体どうしたらいいのよ？\nあたし、そういうの\n苦手なんだけど…", 80003, 0, 106001, "キャル", "", 5, 0, 0, 132, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あら、キャルさん\nどうかなさいましたか？\n何かお困りのようですけど", 80003, 1, 190801, "カリン", "", 1, 0, 0, 133, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("げっ…カリンじゃない\nなんでもないわよ！", 80003, 0, 106001, "キャル", "", 6, 0, 0, 134, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうなのですか？\nキャルさんのことですからてっきり\n2.5周年をどう盛り上げたら\nいいか悩んでいるのかと…", 80003, 1, 190801, "カリン", "", 2, 0, 0, 135, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("分かってんじゃないのよ！？\nいっ、いや、違うけどね！\nあたしは別にそんなことで\n悩んでないわよっ？", 80003, 0, 106001, "キャル", "", 7, 0, 0, 136, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふっ…\nこういう時は、真心を込めて\n気持ちをそのまま口にしたら\nいいのではないでしょうか？", 80003, 1, 190801, "カリン", "", 3, 0, 0, 137, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("気持ちを、ねぇ\nそれが一番難しいんじゃない…\nそもそも、あたしは記念日とか\n別にどうだっていいし", 80003, 0, 106001, "キャル", "", 8, 0, 0, 138, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…まあ、ペコリーヌもコロ助も\nやけに楽しそうだったから…\nこういうお祭り騒ぎみたいなのも\nたまにはいいかな、とは思うけど", 80003, 0, 106001, "キャル", "", 9, 0, 0, 139, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なるほどなるほど～\nキャルさんは【美食殿】で祝う\n2.5周年を心から楽しみに\nしている、ということですね！", 80003, 1, 190801, "カリン", "", 4, 0, 0, 140, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はぁ！？\nどこ聞いたらそうなるのよ！\nあたしは別に楽しみになんか…！", 80003, 0, 106001, "キャル", "", 10, 0, 0, 141, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさんの心からの想い\nみなさんにも伝わったでしょうか？\n私も2.5周年が楽しみです！\n以上、カリンがお伝えしました！", 80003, 1, 190801, "カリン", "", 5, 0, 0, 142, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("心からの想いって何なのよ！？\n勝手に人の言葉を\n捻じ曲げんじゃないわよ！\nこのくそ眼鏡ーーーっ！", 80003, 0, 106001, "キャル", "", 11, 0, 0, 143, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさま、もうすぐ\n記念日でございますね\nこういった節目というのは\n感慨深いものでございます", 80003, 0, 105901, "コッコロ", "", 6, 0, 0, 144, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("色んな思い出が蘇ってきますね！\n楽しい出来事が\nいっぱいありました♪", 80003, 1, 105801, "ペコリーヌ", "", 5, 0, 0, 145, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい、そうでございますね\n主さまも【美食殿】の活動の他にも\nいろんなご経験をされたと\n聞いておりますよ", 80003, 0, 105901, "コッコロ", "", 7, 0, 0, 146, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("たしか…ランドソルで話題沸騰と\nなっていた、魔法少女なるものに\nお会いになられたとか", 80003, 0, 105901, "コッコロ", "", 8, 0, 0, 147, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("魔法少女って、あの美味しくって\n栄養たっぷりの大ヒット商品\n『魔法少女ソーセージ』の箱に\n描いてある女の子のことですか！？", 80003, 1, 105801, "ペコリーヌ", "", 6, 0, 0, 148, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あのソーセージ\n美味しいんですよね～♪\nわたしもたっくさん食べてますよ！", 80003, 1, 105801, "ペコリーヌ", "", 7, 0, 0, 149, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あとは、牧場に素敵な温泉が\n出来たとか…", 80003, 0, 105901, "コッコロ", "", 9, 0, 0, 150, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("牧場ですか！？　温泉につかって\nチーズもオツですね～♪　考えた\nだけでよだれが出ちゃいそうです！\nやばいですね☆", 80003, 1, 105801, "ペコリーヌ", "", 8, 0, 0, 151, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさま\n言ってるそばからよだれが…\n今お拭きしますね。ふき、ふき", 80003, 0, 105901, "コッコロ", "", 10, 0, 0, 152, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えへへ、ありがとうございます\nコッコロちゃん！", 80003, 1, 105801, "ペコリーヌ", "", 9, 0, 0, 153, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それにしても、主さまは\n【美食殿】の一員として様々な\n美食と出会われていたのですね\nわたくし、感服いたしました", 80003, 0, 105901, "コッコロ", "", 11, 0, 0, 154, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからもたくさん冒険をして\nめいっぱい美食を\n味わい尽くしましょうね！", 80003, 1, 105801, "ペコリーヌ", "", 10, 0, 0, 155, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年カウントダウン♪\nキャルちゃんキャルちゃん！\nわくわくしますね☆", 80003, 0, 105801, "ペコリーヌ", "", 11, 0, 0, 156, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あぁもう、うるさいわね～\nまだまだ先でしょ？\nちょっとは落ち着きなさいよ", 80003, 1, 106001, "キャル", "", 12, 0, 0, 157, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルちゃんだって最近\nソワソワしてるじゃないですか～\nさっきもご機嫌そうに鼻歌とか\n歌ってましたよね？", 80003, 0, 105801, "ペコリーヌ", "", 12, 0, 0, 158, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なっ…！　き、聞いてたの！？\nじゃない、歌ってないわよ！？\nあんたいい加減なこと言うと\nぶっ殺すわよ！？", 80003, 1, 106001, "キャル", "", 13, 0, 0, 159, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっへへ～♪\nわたしは最近のキャルちゃんが\nもっともっと大好きですよ♪\nすごく積極的になりましたよね！", 80003, 0, 105801, "ペコリーヌ", "", 13, 0, 0, 160, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…積極的？\nなんの話よ？", 80003, 1, 106001, "キャル", "", 14, 0, 0, 161, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("またまた～♪\nアイドルを目指そうとしたこと\n忘れちゃったんですか？", 80003, 0, 105801, "ペコリーヌ", "", 14, 0, 0, 162, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ムーサの町で\nきゃるきゃる～ん☆　って！", 80003, 0, 105801, "ペコリーヌ", "", 15, 0, 0, 163, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あっ…！？　ちちち違うわよっ！\nあれは操られてただけで\nあたしはアイドルなんか\n目指してないっての！！", 80003, 1, 106001, "キャル", "", 15, 0, 0, 164, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("本当に本当ですか？\nわたし、キャルちゃんとっても\n乗り気だなって\n思ってたんですけど～", 80003, 0, 105801, "ペコリーヌ", "", 16, 0, 0, 165, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まぁ、悪くはなかったけど…って\nだ、だから目指してないって\n言ってるでしょ！！\nなんてこと思い出させんのよ！？", 80003, 1, 106001, "キャル", "", 16, 0, 0, 166, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ああ…ダメだわ…\nもう殺すしかない…\n2.5周年が来る前に\n記憶ごと消し去ってやるー！", 80003, 1, 106001, "キャル", "", 17, 0, 0, 167, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年まであと10日…\nふ～ん？\n案外早いもんね？", 80003, 0, 106001, "キャル", "", 18, 0, 0, 168, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうでございますね…\nその日のためにやるべきことは\nまだまだございます\n気を引き締めねばなりません…！", 80003, 1, 105901, "コッコロ", "", 12, 0, 0, 169, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("やる気十分ねコロ助…\nそんな気負ってるとしんどいわよ？\nお気楽にやりましょ？", 80003, 0, 106001, "キャル", "", 19, 0, 0, 170, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま…\nありがとうございます\nキャルさまは本当に\n優しいおかたです", 80003, 1, 105901, "コッコロ", "", 13, 0, 0, 171, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("な、なにわけの分かんないこと\n言ってんのよ…\nあたしは優しくなんかないっての", 80003, 0, 106001, "キャル", "", 20, 0, 0, 172, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなことはございません\n…あの、実はわたくし\nキャルさまに\nひとつお願いがございまして", 80003, 1, 105901, "コッコロ", "", 14, 0, 0, 173, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お願い？　珍しいわね\nコロ助がそんなこと言うなんて\n…まあ、あたしに出来ることなら\n別にいいけど", 80003, 0, 106001, "キャル", "", 21, 0, 0, 174, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ありがとうございます\n実は記念日へ向けて\n『かくし芸』というものを\n用意してみようかと思いまして", 80003, 1, 105901, "コッコロ", "", 15, 0, 0, 175, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("かくし芸？", 80003, 0, 106001, "キャル", "", 22, 0, 0, 176, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。きゃるきゃる～ん☆　を\n参考に、ころころ～ん☆　という\nご挨拶を考えてみたのですが\nポーズがうまくいかなくて…", 80003, 1, 105901, "コッコロ", "", 16, 0, 0, 177, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("～～！！　ちょっと褒められて\nいい気になって損したわ！！\nふざけんなふざけんな\nふ～ざ～け～ん～な～っ！！", 80003, 0, 106001, "キャル", "", 23, 0, 0, 178, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あと９日！　もうすぐですよ♪\nえへへ、楽しみで楽しみで\nごはんが進みますね☆", 80003, 0, 105801, "ペコリーヌ", "", 17, 0, 0, 179, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ごはんが進みますね☆\nじゃなーい！\nいくらなんでも食べ過ぎよ！\n記念日、迎えられなくなるわよ！？", 80003, 2, 106001, "キャル", "", 24, 0, 0, 180, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫ですよキャルさま\n食事はわたくしたちの\n歩んできた道そのもの\nなのですから", 80003, 1, 105901, "コッコロ", "", 17, 0, 0, 181, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さっすがコッコロちゃん\nいいことを言いますね！\nそう、わたしたち\n【美食殿】の活動目的は─", 80003, 0, 105801, "ペコリーヌ", "", 18, 0, 0, 182, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("─みんなで楽しく食事をすること\nでしょ？\nあれだけ食べ歩いてきたんだから\n分かってるわよ", 80003, 2, 106001, "キャル", "", 25, 0, 0, 183, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい…そうでございますね♪\nそれにしてもわたくしたち\n本当にいろいろなものを\n食べ歩いてきましたね…", 80003, 1, 105901, "コッコロ", "", 18, 0, 0, 184, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうね…ほんっとうにね…\n毒まみれのニセドラゴンとか\n恐竜…は逃げられちゃったっけ\nあとワニゴ…ワニの魔物とかね", 80003, 2, 106001, "キャル", "", 26, 0, 0, 185, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そして、とうとう本物の\nドラゴンまで相手に\nしちゃったのよね、あたしたちって", 80003, 2, 106001, "キャル", "", 27, 0, 0, 186, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("信じられない強さだったわね\nあのドラゴン…やっぱり\n作戦はしっかり立てていかないと\nダメよね", 80003, 2, 106001, "キャル", "", 28, 0, 0, 187, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えへへ…☆\nキャルちゃんが色んなことを\n覚えていてくれて\nうれしいです♪", 80003, 0, 105801, "ペコリーヌ", "", 19, 0, 0, 188, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくしも鮮明に覚えておりますよ\n主さまもきっと…♪", 80003, 1, 105901, "コッコロ", "", 19, 0, 0, 189, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あったり前でしょ！\n忘れないわよ、あんな滅茶苦茶な\nものばかり食べさせられて！\n…忘れられるわけ、ないじゃない", 80003, 2, 106001, "キャル", "", 29, 0, 0, 190, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ねえちょっと、ちょっと待って！？\nカリンから、2.5周年記念の\n生放送に出演してほしいって\n言われたんだけど！", 80003, 0, 106001, "キャル", "", 30, 0, 0, 191, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なんでそういう大事なことを\n急に言うわけ！？\nそんなの聞いてないわよ～！？", 80003, 0, 106001, "キャル", "", 31, 0, 0, 192, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いっぱい人に見られちゃうのよね？\nなんであたしがそんなこと…", 80003, 0, 106001, "キャル", "", 32, 0, 0, 193, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あー\nあー\n…声、これで大丈夫かしら？", 80003, 0, 106001, "キャル", "", 33, 0, 0, 194, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聞き取りにくいかもしれないわね…\nもうちょっと明るい方がいいかも\nえっと…こんな感じ？", 80003, 0, 106001, "キャル", "", 34, 0, 0, 195, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", 80003, 0, 106001, "キャル", "", 35, 0, 0, 196, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("……\nいや、ないわ\nいつもどおりが一番ね、うん", 80003, 0, 106001, "キャル", "", 36, 0, 0, 197, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう、記念の生放送なんて\n超責任重大なやつじゃない…\nもしなにか失敗とかしたら…", 80003, 0, 106001, "キャル", "", 37, 0, 0, 198, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ど、どど、どうしよう！？\n緊張してきちゃった…！！", 80003, 0, 106001, "キャル", "", 38, 0, 0, 199, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("主さま、わたくし\nペコリーヌさまとキャルさまと共に\n2.5周年を祝う生放送に\n出演する大役を仰せつかりました", 80003, 0, 105901, "コッコロ", "", 20, 0, 0, 200, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("多くの方々に\n『プリンセスコネクト！\nRe:Dive』の魅力をお伝えする\n重要な役割でございます", 80003, 0, 105901, "コッコロ", "", 21, 0, 0, 201, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくし、全身全霊をもって\n生放送に取り組みたいと\n思っております", 80003, 0, 105901, "コッコロ", "", 22, 0, 0, 202, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですが、もしかしたら\nセリフを噛んでしまったり\n段取りを間違えてしまったり\nするかもしれません…", 80003, 0, 105901, "コッコロ", "", 23, 0, 0, 203, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そのようなことがないよう\n練習はしっかりしておかなくては\nまずはこちらから…", 80003, 0, 105901, "コッコロ", "", 24, 0, 0, 204, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", 80003, 0, 105901, "コッコロ", "", 25, 0, 0, 205, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("先ほどキャルさまが練習されて\nいるのをお見かけしたので\nわたくしもと思いまして…\nいかがでしょうか？", 80003, 0, 105901, "コッコロ", "", 26, 0, 0, 206, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("良い感じ、ですか？\n…ふふ、ありがとうございます\n主さまのあたたかいお言葉があれば\nわたくしは百人力でございます", 80003, 0, 105901, "コッコロ", "", 27, 0, 0, 207, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この大役を無事に成し遂げ\n主さまに素敵な2.5周年を\n迎えていただけるよう…\nわたくし、尽力いたしますね", 80003, 0, 105901, "コッコロ", "", 28, 0, 0, 208, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", 80003, 0, 105801, "ペコリーヌ", "", 20, 0, 0, 209, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…う～ん、今のはちょっと\n違う感じがしますね\n堅苦しかったかもしれません", 80003, 0, 105801, "ペコリーヌ", "", 21, 0, 0, 210, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あと６日で2.5周年ですか…", 80003, 0, 105801, "ペコリーヌ", "", 22, 0, 0, 211, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この年月がオイッスーの\n歴史なんだと思うと\nじ～んとしちゃいます！\nやばいですね☆", 80003, 0, 105801, "ペコリーヌ", "", 23, 0, 0, 212, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("生放送で最高のオイッスー☆　を\nみなさんにお届けするために\n頑張らないと！\nそれじゃあもう一度…", 80003, 0, 105801, "ペコリーヌ", "", 24, 0, 0, 213, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", 80003, 0, 105801, "ペコリーヌ", "", 25, 0, 0, 214, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…うう～ん、どうしてでしょう\nまだ何かが違う気がします…\nもしかしたら\nおなかが空きすぎてるとか？", 80003, 0, 105801, "ペコリーヌ", "", 26, 0, 0, 215, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今さっき食べたばっかりですけど\nおなかが減っては\n良いオイッスー☆　は\n出せませんよね！", 80003, 0, 105801, "ペコリーヌ", "", 27, 0, 0, 216, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうと決まれば、コッコロちゃんと\nキャルちゃんを誘って\nごはんにしましょう！\n善は急げです！", 80003, 0, 105801, "ペコリーヌ", "", 28, 0, 0, 217, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、二人が丁度いいところに！\nオイッス～☆　…ああ！！\n今の、今のですよ～♪", 80003, 0, 105801, "ペコリーヌ", "", 29, 0, 0, 218, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なるほど、どんな時も\n自然体が一番ってことですね！\nこの調子で、生放送も\n頑張っちゃいます♪", 80003, 0, 105801, "ペコリーヌ", "", 30, 0, 0, 219, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年まで残り５日ですが\nその前にもうすぐ生放送ですよ！\nコッコロちゃん\n準備の方はどうですか？", 80003, 0, 105801, "ペコリーヌ", "", 31, 0, 0, 220, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。わたくし、しっかりと\n備えてまいりました\n万事抜かりはございません", 80003, 1, 105901, "コッコロ", "", 29, 0, 0, 221, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おお～すごい自信を感じます…！\nいい生放送になりそうですね☆\n……あれ？　なんだかこの辺り\n揺れていませんか？", 80003, 0, 105801, "ペコリーヌ", "", 32, 0, 0, 222, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…………", 80003, 2, 106001, "キャル", "", 39, 0, 0, 223, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま？\nお風邪をひかれたんでしょうか\nひどい震えですが…", 80003, 1, 105901, "コッコロ", "", 30, 0, 0, 224, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("かかかか風邪じゃないわよ！\nここここれはただ\nななな生放送が楽しみ過ぎて\nワワワワクワクが止まらないだけ！", 80003, 2, 106001, "キャル", "", 40, 0, 0, 225, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫ですかキャルちゃん！？\nそうだ、これを飲んでください！", 80003, 0, 105801, "ペコリーヌ", "", 33, 0, 0, 226, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("きき気がきくじゃない、ありがとっ\nごくっ、んく…ぶはぁっ！？\nちょっと何飲ませたの！？\n辛っ！　苦ぁ！？　甘ぁっ！？", 80003, 2, 106001, "キャル", "", 41, 0, 0, 227, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これは魔物のエキスに薬草に\nその他色んなものを混ぜた\n特製の栄養ドリンクです！", 80003, 0, 105801, "ペコリーヌ", "", 34, 0, 0, 228, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これを飲めば体ぽかぽかで\n元気いっぱいですよ♪", 80003, 0, 105801, "ペコリーヌ", "", 35, 0, 0, 229, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("このアホリーヌ！\n風邪じゃないって言ったでしょ！？\nどさくさに紛れて\nそんな恐ろしいもん飲ませんな～！", 80003, 2, 106001, "キャル", "", 42, 0, 0, 230, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま\n震えが収まっておりますね\nよかったです…\nわたくし、心配いたしました", 80003, 1, 105901, "コッコロ", "", 31, 0, 0, 231, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え？　ああ、ホントね…って\nだから風邪じゃないって\n言ってるのに…\nまあいいわこの際なんでも", 80003, 2, 106001, "キャル", "", 43, 0, 0, 232, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっへへ～♪　いつも通りの\nキャルちゃんに戻りましたし\n素敵な生放送が出来そうですね！\n今から楽しみです☆", 80003, 0, 105801, "ペコリーヌ", "", 36, 0, 0, 233, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ランドソルのみなさま、こんにちは\n生放送の会場設営を担当しています\n【ギルド管理協会】のカリンです", 80003, 0, 190801, "カリン", "", 6, 0, 0, 234, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】のみなさんは\nまもなく始まる生放送に向けて\n最後の調整のため\n席を外しています", 80003, 0, 190801, "カリン", "", 7, 0, 0, 235, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("頑張っている３人の\n邪魔をするわけには\nいきませんので、ご容赦ください", 80003, 0, 190801, "カリン", "", 8, 0, 0, 236, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですので、本日は私から\n【美食殿】のみなさんの様子を\nお伝えさせていただこうと思います", 80003, 0, 190801, "カリン", "", 9, 0, 0, 237, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まずはペコリーヌさんですが…\n何やら大量のおにぎりを\n食べているようです\nえっと…栄養は大事ですよね", 80003, 0, 190801, "カリン", "", 10, 0, 0, 238, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("次にコッコロさんですが\nこちらは発声練習をしています", 80003, 0, 190801, "カリン", "", 11, 0, 0, 239, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("一生懸命、小さなお口を開けて\n声を出す姿が応援したくなりますね", 80003, 0, 190801, "カリン", "", 12, 0, 0, 240, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そしてキャルさんは…\nこれは…堂々としたものですね\n何もせず、ただ立ち尽くして…", 80003, 0, 190801, "カリン", "", 13, 0, 0, 241, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれ？\nもしかして緊張で気を失って…？", 80003, 0, 190801, "カリン", "", 14, 0, 0, 242, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ええと\n【美食殿】のみなさんは\nやる気十分なようですね！", 80003, 0, 190801, "カリン", "", 15, 0, 0, 243, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("３人とも生放送を\nいいものにしようと\n全力で頑張ってくれていますので\nどうかご期待ください", 80003, 0, 190801, "カリン", "", 16, 0, 0, 244, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは\nまた明日お会いしましょう♪", 80003, 0, 190801, "カリン", "", 17, 0, 0, 245, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年まであと３日！\nそして生放送は明日！\nなんかいよいよって感じね…", 80003, 0, 106001, "キャル", "", 44, 0, 0, 246, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("３人でい～っぱい練習しましたし\nきっと大丈夫ですよ☆", 80003, 2, 105801, "ペコリーヌ", "", 37, 0, 0, 247, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさまに\n大丈夫と言ってもらえると\nとても心強いですね", 80003, 1, 105901, "コッコロ", "", 32, 0, 0, 248, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("信じすぎちゃだめよコロ助\nこいつはなーんにも\n考えてないだけなんだから", 80003, 0, 106001, "キャル", "", 45, 0, 0, 249, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ひどいですよぉキャルちゃ～ん！", 80003, 2, 105801, "ペコリーヌ", "", 38, 0, 0, 250, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。お二人とも\n普段通りの様子で\n安心いたしました", 80003, 1, 105901, "コッコロ", "", 33, 0, 0, 251, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はいっ☆\n生放送でもなんでも\n全力全開、わたしらしく\nぶつかっていくだけです！", 80003, 2, 105801, "ペコリーヌ", "", 39, 0, 0, 252, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうね。おめでたいことなんだし\nここまで来たんなら\n楽しめるだけ\n楽しむしかないわよね！", 80003, 0, 106001, "キャル", "", 46, 0, 0, 253, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくしも、普段よりも心が\n熱くなっております\nこの胸の気持ちをお伝えできるよう\n精一杯努力いたします…！", 80003, 1, 105901, "コッコロ", "", 34, 0, 0, 254, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは、いきましょう！\n明日の生放送、絶対に\n成功させましょうね☆", 80003, 2, 105801, "ペコリーヌ", "", 40, 0, 0, 255, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっと、最初のひと言は…あれ？\nキャルちゃん、わたし\n何て言うんでしたっけ？", 80003, 0, 105801, "ペコリーヌ", "", 41, 0, 0, 256, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("は！？\nなにいきなりど忘れしてるの！？\nっていうかあんた、台本は！？", 80003, 2, 106001, "キャル", "", 47, 0, 0, 257, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("忘れてきちゃいました☆", 80003, 0, 105801, "ペコリーヌ", "", 42, 0, 0, 258, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("忘れてきちゃいました☆\nで済ませられると思ってんの！？\nほら、あたし二冊持ってきたから\nこれ使いなさい！", 80003, 2, 106001, "キャル", "", 48, 0, 0, 259, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("マイクとは、こんな高い位置に\nあるものなのですね…！\n背伸びをすれば、何とか…\nう～ん、うぅ～ん…！", 80003, 1, 105901, "コッコロ", "", 35, 0, 0, 260, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あぁもう\n少し下げればいいでしょ！？\nこれくらいでいい？\nまったく、世話が焼けるわね…", 80003, 2, 106001, "キャル", "", 49, 0, 0, 261, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれ？\nキャルちゃん、後ろ髪が\nはねちゃってますよ？", 80003, 0, 105801, "ペコリーヌ", "", 43, 0, 0, 262, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え？　うそっ！？\nちゃんと確かめてきたのに！\nどこどこ！？", 80003, 2, 106001, "キャル", "", 50, 0, 0, 263, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま、動かないで\nくださいまし。今くしで…\nはい、直りましたよ", 80003, 1, 105901, "コッコロ", "", 36, 0, 0, 264, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、ありがと…はぁ。生放送\n本番までもうすぐなのに\nこんなことしてる場合じゃ\nないわよね", 80003, 2, 106001, "キャル", "", 51, 0, 0, 265, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい、時間は残りわずかです\nですが、慌ただしく\n動き回るこの時間も\nなんだか楽しくて…♪", 80003, 1, 105901, "コッコロ", "", 37, 0, 0, 266, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("コロ助、あんた…って\nそうじゃなくて！\n胸にジンワリきてる\n暇なんかないでしょ…！？", 80003, 2, 106001, "キャル", "", 52, 0, 0, 267, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あはは♪\nキャルちゃんの動きが\nとっても面白いです♪\nやばいですね☆", 80003, 0, 105801, "ペコリーヌ", "", 44, 0, 0, 268, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ\nきっと面白い生放送になると\nわたくし、確信しております", 80003, 1, 105901, "コッコロ", "", 38, 0, 0, 269, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("絶対絶対、間違いありません！\n見てくれるみなさんが\n笑顔になれる時間を\nお届けしましょう！", 80003, 0, 105801, "ペコリーヌ", "", 45, 0, 0, 270, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなの当然でしょ！\n誰が見たって面白いって\n言ってもらえるように\nあれだけ準備したんだから！", 80003, 2, 106001, "キャル", "", 53, 0, 0, 271, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは\n記念日直前生放送！\n楽しみにしててくださいね☆", 80003, 0, 105801, "ペコリーヌ", "", 46, 0, 0, 272, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こんにちは\n【ギルド管理協会】のカリンです", 80003, 0, 190801, "カリン", "", 18, 0, 0, 273, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("昨日の生放送は\nいかがだったでしょうか？", 80003, 0, 190801, "カリン", "", 19, 0, 0, 274, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("たくさんの笑顔と喜びと\nそして驚きを受け取って\nいただけたのではないかと思います", 80003, 0, 190801, "カリン", "", 20, 0, 0, 275, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そしていよいよ\n明日は2.5周年の当日\n待ちに待った記念日を\n迎えることとなります", 80003, 0, 190801, "カリン", "", 21, 0, 0, 276, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】のみなさんも\n張り切って様々な準備を\nされていますよ", 80003, 0, 190801, "カリン", "", 22, 0, 0, 277, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【ギルド管理協会】も\n万全のサポート体制で\n協力してまいりたいと思います", 80003, 0, 190801, "カリン", "", 23, 0, 0, 278, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ふふ、本当に楽しみですね\n【ギルド管理協会】の職員として\nだけではなく、私個人としても…", 80003, 0, 190801, "カリン", "", 24, 0, 0, 279, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この記念日を迎えられることが\n心から楽しみですし\n幸せを感じています", 80003, 0, 190801, "カリン", "", 25, 0, 0, 280, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("きっと【美食殿】のみなさんは\nそれ以上に心を弾ませて\nいることでしょう", 80003, 0, 190801, "カリン", "", 26, 0, 0, 281, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは\n明日からの2.5周年を\nどうぞ、お楽しみに…♪", 80003, 0, 190801, "カリン", "", 27, 0, 0, 282, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("準備はいいですかっ？\n…いっきますよー！", 80003, 0, 105801, "ペコリーヌ", "", 47, 0, 0, 283, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("祝！", 80003, 2, 106001, "キャル", "", 54, 0, 0, 284, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年！", 80003, 1, 105901, "コッコロ", "", 39, 0, 0, 285, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おめでとうございま～す☆", 80003, 0, 105801, "ペコリーヌ", "", 48, 0, 0, 286, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("少し前まではまだまだ先じゃない\nとか言ってたけど\n本当にあっという間だったわね", 80003, 2, 106001, "キャル", "", 55, 0, 0, 287, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("光陰矢の如し…\nとはこのことでございますね\nでも、今日という日を無事に\n迎えることができて良かったです", 80003, 1, 105901, "コッコロ", "", 40, 0, 0, 288, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("コッコロちゃん！　キャルちゃん！\n落ち着くには\nまだ早いですよ！\n盛り上がるのはこれからです☆", 80003, 0, 105801, "ペコリーヌ", "", 49, 0, 0, 289, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ほんとあんたはいつも\n全力全開ねー\nでもそうね、記念日なんだし\nパーっといきましょ！", 80003, 2, 106001, "キャル", "", 56, 0, 0, 290, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええ、わたくしも全力全開で\nまいります…！\n主さま、さあ\nどうぞ手を取ってくださいまし…♪", 80003, 1, 105901, "コッコロ", "", 41, 0, 0, 291, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あんたもコロ助も、浮かれて\n転ぶんじゃないわよ？\n…仕方ないから、あたしも\n手を繋いであげるわよ", 80003, 2, 106001, "キャル", "", 57, 0, 0, 292, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あー！　二人ともずるいです！\nわたしもっ、ギュー♪", 80003, 0, 105801, "ペコリーヌ", "", 50, 0, 0, 293, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ちょっ、ペコリーヌ！\nくっつき過ぎよ！", 80003, 2, 106001, "キャル", "", 58, 0, 0, 294, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("記念日だから\n平気平気♪\nやばいですね☆", 80003, 0, 105801, "ペコリーヌ", "", 51, 0, 0, 295, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("意味分かんないわよ！", 80003, 2, 106001, "キャル", "", 59, 0, 0, 296, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。このめでたき日に\n喜びがあふれておりますね\n主さまは…いかがでしょうか？", 80003, 1, 105901, "コッコロ", "", 42, 0, 0, 297, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("喜んでいただけているならば\nわたくしはとてもとても\n幸せでございます", 80003, 1, 105901, "コッコロ", "", 43, 0, 0, 298, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さぁ、2.5周年を\n楽しみ尽くしますよ☆\nまだまだ食べたいものもありますし\nやりたいこともたくさんです！", 80003, 0, 105801, "ペコリーヌ", "", 52, 0, 0, 299, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("分かった、分かったから\n引っ張るんじゃないわよ！\n…そんな掴まなくても\nちゃんとついていくから", 80003, 2, 106001, "キャル", "", 60, 0, 0, 300, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさま…キャルさま…\n主さま…共にまいりましょう\nどこまでも…！", 80003, 1, 105901, "コッコロ", "", 44, 0, 0, 301, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい！　それでは2.5周年\n食べつくしツアーへ！\nそして、その先の未来へ\n向かって出発しましょう！", 80003, 0, 105801, "ペコリーヌ", "", 53, 0, 0, 302, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年\nありがとうございます！", 80003, 0, 105801, "ペコリーヌ・コッコロ・キャル", "105901,45,106001,61", 54, 1, 0, 303, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 60002, 1, 190804, "カリン", "", 1, 0, 0, 304, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 60002, 2, 0, "", "", 0, 0, 1, 305, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60002, 2, 0, "", "", 0, 0, 1, 306, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", 60002, 2, 0, "", "", 0, 0, 1, 307, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", 60002, 2, 0, "", "", 0, 0, 1, 308, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 60002, 2, 0, "", "", 0, 0, 1, 309, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 60002, 2, 0, "", "", 0, 0, 2, 310, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 60002, 2, 0, "", "", 0, 0, 2, 311, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", 60002, 2, 0, "", "", 0, 0, 2, 312, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", 60002, 2, 0, "", "", 0, 0, 2, 313, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 60002, 2, 0, "", "", 0, 0, 2, 314, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 60002, 2, 0, "", "", 0, 0, 3, 315, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 60002, 2, 0, "", "", 0, 0, 3, 316, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60002, 2, 0, "", "", 0, 0, 3, 317, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 60002, 2, 0, "", "", 0, 0, 3, 318, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたい焼き！　和菓子パワーで売上アップです！", 60002, 2, 0, "", "", 0, 0, 3, 319, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60002, 2, 0, "", "", 0, 0, 3, 320, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかのごとく、色々な事がうまくいきますよ♪", 60002, 2, 0, "", "", 0, 0, 3, 321, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", 60002, 2, 0, "", "", 0, 0, 4, 322, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 60002, 2, 0, "", "", 0, 0, 4, 323, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", 60002, 2, 0, "", "", 0, 0, 4, 324, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", 60002, 2, 0, "", "", 0, 0, 4, 325, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", 60002, 2, 0, "", "", 0, 0, 4, 326, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", 60002, 2, 0, "", "", 0, 0, 4, 327, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", 60002, 2, 0, "", "", 0, 0, 4, 328, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 60002, 3, 190804, "カリン", "", 2, 0, 0, 329, 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 60002, 3, 190804, "カリン", "", 3, 0, 0, 330, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ささ、シェフィさまはこちらへ…", 80005, 4, 105901, "コッコロ", "", 1, 0, 0, 331, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("コッコロさん、どこへ行くの…？\n…え？", 80005, 0, 106401, "シェフィ", "", 1, 0, 0, 332, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("『おめでとうございます！\nわ～パチパチー！』\n…という感じでどうですかね！？", 80005, 3, 105801, "ペコリーヌ", "", 1, 0, 0, 333, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ではわたくしも\n後ろからクラッカーを鳴らして\n応戦いたします\nああ、当日が待ち遠しいですね", 80005, 4, 105901, "コッコロ", "", 2, 0, 0, 334, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…\n二人とも何をしているの？", 80005, 0, 106401, "シェフィ", "", 2, 0, 0, 335, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィは初めてだもんね\nあの日が近いからって\n予行練習してんのよ\n気が早いわよね～", 80005, 1, 106001, "キャル", "", 1, 0, 0, 336, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あの日…？", 80005, 0, 106401, "シェフィ", "", 3, 0, 0, 337, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("その通りです…\nいよいよ記念すべきあの日が\n近づいてきましたよ！", 80005, 3, 105801, "ペコリーヌ", "", 2, 0, 0, 338, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("『プリンセスコネクト！\nRe:Dive』3.5周年！", 80005, 3, 105801, "ペコリーヌ", "", 3, 0, 0, 339, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("やばいですね☆", 80005, 2, 190801, "カリン", "", 1, 0, 0, 340, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("って、なにしれっと\n参加してんのよカリン！", 80005, 1, 106001, "キャル", "", 2, 0, 0, 341, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ、いいじゃないですか\n【ギルド管理協会】として\n私もみなさんと一緒に\nお祝いをさせてください！", 80005, 2, 190801, "カリン", "", 2, 0, 0, 342, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それに…記念日が近づけば\nとっておきの情報を\nお届けしますから♪", 80005, 2, 190801, "カリン", "", 3, 0, 0, 343, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("というわけで\n今日からシェフィちゃんも一緒に\nカウントダウンしちゃいましょう！\n3.5周年まで…", 80005, 3, 105801, "ペコリーヌ", "", 4, 0, 0, 344, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ！？　ええとええと…！\nあ、あと14日…！", 80005, 0, 106401, "シェフィ", "", 4, 0, 0, 345, 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと13日\n豪華に、そして盛大に\nお祝いしたいですね☆", 80005, 3, 105801, "ペコリーヌ", "", 5, 0, 0, 346, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("豪華といえば前にとある貴族さまが\n舞踏会を開かれたそうで\n主さまがそのお手伝いを\nしておりました", 80005, 1, 105901, "コッコロ", "", 3, 0, 0, 347, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そこで美しい所作を学ばれたので\nわたくしも教えていただきました\nしゃなり、しゃなり…\nいかがでしょう？", 80005, 1, 105901, "コッコロ", "", 4, 0, 0, 348, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("すっごく上手ですよ☆\nまるでお姫様みたいです\nせっかくなのでわたしも\nしゃなりしゃなり", 80005, 3, 105801, "ペコリーヌ", "", 6, 0, 0, 349, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さすがでございます\nペコリーヌさま", 80005, 1, 105901, "コッコロ", "", 5, 0, 0, 350, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いや、あんたは\nできなきゃダメでしょ\n本物のお姫様なんだし", 80005, 0, 106001, "キャル", "", 3, 0, 0, 351, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("しゃなり、しゃなり…\nふふ、案外できるものね", 80005, 2, 106401, "シェフィ", "", 5, 0, 0, 352, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わぁ！\nシェフィちゃん\n姿勢がとってもキレイです♪", 80005, 3, 105801, "ペコリーヌ", "", 7, 0, 0, 353, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さ、次はキャルさまの\n番でございますよ", 80005, 1, 105901, "コッコロ", "", 6, 0, 0, 354, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、あたしはいいわよ！\nそういうの全然分かんないし…", 80005, 0, 106001, "キャル", "", 4, 0, 0, 355, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫\nやってみると結構楽しいわよ\nほらほらっ", 80005, 2, 106401, "シェフィ", "", 6, 0, 0, 356, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そ、そこまで言うなら…\nしゃなにゅわきゃあっ！", 80005, 0, 106001, "キャル", "", 5, 0, 0, 357, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いたたた…もぉお～！\nなんであたしがこんな目に～！", 80005, 0, 106001, "キャル", "", 6, 0, 0, 358, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まぁまぁ\n記念日までに練習すれば\nできるようになるかもしれません\nよろしければお教えいたしますよ", 80005, 1, 105901, "コッコロ", "", 7, 0, 0, 359, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("よし！\nあんたたちができて\nあたしだけできないのはしゃくだし\nやってやろうじゃないの！！", 80005, 0, 106001, "キャル", "", 7, 0, 0, 360, 0, 2);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと12日\n記念日当日はもちろんですが\nその日を待つ時間というのも\n心躍ります", 80005, 1, 105901, "コッコロ", "", 8, 0, 0, 361, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("分かりますっ！\nどんな特別な料理を食べられるのか\n考えるだけでワクワクしますよね！", 80005, 3, 105801, "ペコリーヌ", "", 8, 0, 0, 362, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("特別な料理といえば、お祭りですね\nそういえば主さまは学生として\n聖学祭に参加されたこと\nがあるとか…", 80005, 1, 105901, "コッコロ", "", 9, 0, 0, 363, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聖学祭…って、なにかしら？", 80005, 2, 106401, "シェフィ", "", 7, 0, 0, 364, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聖テレサ女学院の祭典ですよ\n二つのチームが競い合い\n青春を満喫するのが趣旨のようです", 80005, 1, 105901, "コッコロ", "", 10, 0, 0, 365, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それってカルミナの\nサプライズライブがあった\nお祭りよね？\nちょっと見たかったかも…", 80005, 0, 106001, "キャル", "", 8, 0, 0, 366, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("カルミナの後の\nライブも好評だったらしいじゃない\n確か、なかよし部\nだったっけ…？", 80005, 0, 106001, "キャル", "", 9, 0, 0, 367, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なかよし部…\n仲が良さそうな名前で\nやばいですね☆", 80005, 3, 105801, "ペコリーヌ", "", 9, 0, 0, 368, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いや、そのまんますぎでしょ…", 80005, 0, 106001, "キャル", "", 10, 0, 0, 369, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聖学祭かぁ…なんだか楽しそうね\nそれになかよし部の人たちも\n気になるわ", 80005, 2, 106401, "シェフィ", "", 8, 0, 0, 370, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それじゃあわたしたちも、\n負けじと仲良くしましょう♪\nほらほらシェフィちゃん、\nぎゅーっ☆　ですよ♪", 80005, 3, 105801, "ペコリーヌ", "", 10, 0, 0, 371, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ？　ええ…\nぎゅーっ…？", 80005, 2, 106401, "シェフィ", "", 9, 0, 0, 372, 0, 3);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと11日！？\nお祝いの準備進んでないんだけど…\nああ～昨日に戻りたいわ…", 80005, 0, 106001, "キャル", "", 11, 0, 0, 373, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そういえばそんな魔道具があるって\n聞いたことがあるわね\n確か、名前はタイムラーベ…", 80005, 2, 106401, "シェフィ", "", 10, 0, 0, 374, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なにそれヤバいわね\nでも本当にあるんだったら\n準備よりももっとやり直したいこと\nたくさんあるんだけど…", 80005, 0, 106001, "キャル", "", 12, 0, 0, 375, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もしや正月の件でしょうか…？\nあの時はお金がなくて\n苦労しましたから", 80005, 1, 105901, "コッコロ", "", 11, 0, 0, 376, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれはそうね…\nお金を湯水のように使う\nぺコリーヌを止められたら\nあんな苦労をすることもなかったし", 80005, 0, 106001, "キャル", "", 13, 0, 0, 377, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなこともありましたね！\nやり直したいといえば\n『きゃるきゃる～ん♪』\nの方かと思いましたよ！", 80005, 3, 105801, "ペコリーヌ", "", 11, 0, 0, 378, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("バラすんじゃないわよ\nこのアホリーヌ！\nシェフィはそれ\n知らないんだから！", 80005, 0, 106001, "キャル", "", 14, 0, 0, 379, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こうなったらもう、なんとか\nタイムラーべを探し出して\n今の会話をなかったことに…\nって、どうしたのよシェフィ", 80005, 0, 106001, "キャル", "", 15, 0, 0, 380, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("うん…もし、私だったら…\n私が知らないみんなとの時間を\n見てみたいな、って…", 80005, 2, 106401, "シェフィ", "", 11, 0, 0, 381, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィちゃん！　タイムなんとか\nなんかなくても大丈夫ですよ！\n一緒の時間はこれから\nどんどん作ればいいんですから！", 80005, 3, 105801, "ペコリーヌ", "", 12, 0, 0, 382, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい、今この瞬間も\n未来にはかけがえのない思い出に\nなっていることでしょう", 80005, 1, 105901, "コッコロ", "", 12, 0, 0, 383, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だからそんな顔しないの\nほら、お祝いの準備、進めるわよ！", 80005, 0, 106001, "キャル", "", 16, 0, 0, 384, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("みんな…そうね\n最高のお祝いにして\n最高の思い出にしましょう！", 80005, 2, 106401, "シェフィ", "", 12, 0, 0, 385, 0, 4);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まで、あと10日！\nもうすぐですよー！\n楽しみすぎて、やばいですね！", 80005, 3, 105801, "ペコリーヌ", "", 13, 0, 0, 386, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そういえば…たくさんのおもちゃが\n子どもたちを襲うっていう\n騒動もありましたね…\nなんでも勝手に動き出したとか！", 80005, 3, 105801, "ペコリーヌ", "", 14, 0, 0, 387, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("学校や孤児院とかに\nちっちゃなおもちゃが乗り込んで\n暴れたみたいですよ！", 80005, 3, 105801, "ペコリーヌ", "", 15, 0, 0, 388, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("暴れたって言っても\n所詮はおもちゃじゃない\nどうせちっさいんでしょ？", 80005, 0, 106001, "キャル", "", 17, 0, 0, 389, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だったら魔法で\n全部ぶっ飛ばせばいいじゃない！\n大したことないわよ！", 80005, 0, 106001, "キャル", "", 18, 0, 0, 390, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルってば…\n相手は子どもが\n大事にしてる物なのよ…？", 80005, 2, 106401, "シェフィ", "", 13, 0, 0, 391, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("乱暴な発言は\nめっ、でございますよ？\n子どもの教育に悪影響を\n与えてしまいますから…", 80005, 1, 105901, "コッコロ", "", 13, 0, 0, 392, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルちゃんだって\n意外と猫グッズとか\nたっくさん集めてますよね？\nもしその子たちが暴れたら…？", 80005, 3, 105801, "ペコリーヌ", "", 16, 0, 0, 393, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("う、うっさいわね！\n意外とか言うな！\n…ま、まあ確かに正面切って\n魔法でぶっ飛ばせないかもね…", 80005, 0, 106001, "キャル", "", 19, 0, 0, 394, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あはは☆\nキャルちゃんのそういうところ\n好きですよ♪", 80005, 3, 105801, "ペコリーヌ", "", 17, 0, 0, 395, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなキャルちゃんに猫グッズを\nプレゼントしちゃいますね！\n一部で流行っていた、たい焼き屋の\nおまけフィギュアですよ♪", 80005, 3, 105801, "ペコリーヌ", "", 18, 0, 0, 396, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("乱暴に扱ったりしないでくださいね\nひとりでに暴れ出しちゃうかも\nしれませんから！", 80005, 3, 105801, "ペコリーヌ", "", 19, 0, 0, 397, 0, 5);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと９日\nここでみなさんに\nビックニュースですよ！", 80005, 2, 190801, "カリン", "", 4, 0, 0, 398, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年を祝う生放送に\n去年と同様【美食殿】の\nみなさんにご出演いただくことが\n決定しましたー！", 80005, 2, 190801, "カリン", "", 5, 0, 0, 399, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…えっ！？", 80005, 1, 106001, "キャル", "", 20, 0, 0, 400, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("本当ですか！？\nそれじゃ今から張り切って\n生放送中に食べる魔物料理を\n作らなくちゃですね☆", 80005, 3, 105801, "ペコリーヌ", "", 20, 0, 0, 401, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いや…がんばるところは\nそこじゃないような…\nというか去年も出演してたのね\nすごいじゃない！", 80005, 0, 106401, "シェフィ", "", 14, 0, 0, 402, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。とても緊張しますが\nやりがいのある大役です\n一緒にがんばりましょうね\nシェフィさま", 80005, 4, 105901, "コッコロ", "", 14, 0, 0, 403, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わ、私も出るの！？　でも…\n私も【美食殿】の一人だものね\nそれなら今からしっかり準備をして\nコンディションを整えないと…", 80005, 0, 106401, "シェフィ", "", 15, 0, 0, 404, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふん♪\n生放送直前のカチコチになった\nシェフィの姿が楽しみだわ！", 80005, 1, 106001, "キャル", "", 21, 0, 0, 405, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("去年のキャルちゃんは\n緊張しすぎてずっと震えて\nかわいかったですもんね！\n今年もあの姿が見たいです！", 80005, 3, 105801, "ペコリーヌ", "", 21, 0, 0, 406, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ぶっ殺すぞ！？", 80005, 1, 106001, "キャル", "", 22, 0, 0, 407, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("というわけで\n『プリンセスコネクト！\nRe:Dive』の魅力を\nお伝えする生放送をお楽しみに♪", 80005, 2, 190801, "カリン", "", 6, 0, 0, 408, 0, 6);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと８日\nでございますよ\n楽しみですね、主さま", 80005, 1, 105901, "コッコロ", "", 15, 0, 0, 409, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そういえばあんた\n夏休みの宿題は\nきちんとやってるの？", 80005, 0, 106001, "キャル", "", 23, 0, 0, 410, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("宿題…学校に通うのも\n楽しいことばかりじゃ\nないのね", 80005, 2, 106401, "シェフィ", "", 16, 0, 0, 411, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれ？　そういえば\n少し前にルーセント学院で\n何かあったような…", 80005, 3, 105801, "ペコリーヌ", "", 22, 0, 0, 412, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ああ、始業式の日に\n大捕り物があったって\n話題になってたわね", 80005, 0, 106001, "キャル", "", 24, 0, 0, 413, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("夏休みを終わらせないって\n騒いでたっていう話？\nあれ本当なの？\n都市伝説だと思ってたわ", 80005, 2, 106401, "シェフィ", "", 17, 0, 0, 414, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("その一件ならよく存じ上げて\nおります。ですから主さま\n次の機会にはわたくしと一緒に\nがんばりましょう", 80005, 1, 105901, "コッコロ", "", 16, 0, 0, 415, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("楽しそう…私も一緒にやりたいな\nママ…じゃ、じゃなくて！\nコッコロさん、私もまざっていい？", 80005, 2, 106401, "シェフィ", "", 18, 0, 0, 416, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もちろんでございます\n仲良くお勉強いたしましょう", 80005, 1, 105901, "コッコロ", "", 17, 0, 0, 417, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("しれっと教育ママが\n生まれてる…？", 80005, 0, 106001, "キャル", "", 25, 0, 0, 418, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お勉強は大切ですよ！\nキャルちゃんも一緒に\nがんばりましょう！", 80005, 3, 105801, "ペコリーヌ", "", 23, 0, 0, 419, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え～～～～！？", 80005, 0, 106001, "キャル", "", 26, 0, 0, 420, 0, 7);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと７日〜♪\nふふ～ん♪\nふんふふ～ん♪", 80005, 0, 106001, "キャル", "", 27, 0, 0, 421, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…\nねぇコッコロさん\nキャル、どうしちゃったの？", 80005, 2, 106401, "シェフィ", "", 19, 0, 0, 422, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("とてもご機嫌そうに\n鼻歌を歌ってらっしゃいますね\n耳も尻尾もリズミカルに\n揺れて…ノリノリでございます", 80005, 1, 105901, "コッコロ", "", 18, 0, 0, 423, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれはですね！\nカルミナのみなさんの\nサマーライブのチケットが\n手に入ったからなんですよ♪", 80005, 3, 105801, "ペコリーヌ", "", 24, 0, 0, 424, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええっ！？\nあのライブのチケットって確か\n入手困難だったんじゃ…", 80005, 2, 106401, "シェフィ", "", 20, 0, 0, 425, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふふふ～ん♪\nしゃいにんぐふゅ～ちゃ～♪", 80005, 0, 106001, "キャル", "", 28, 0, 0, 426, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なるほど…\nキャルさまがあのように\nなってしまうのも頷けますね", 80005, 1, 105901, "コッコロ", "", 19, 0, 0, 427, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…カルミナの\n『Shining Future』\nの中に、シャイニングフューチャー\nって歌詞はなかったはずだけど…", 80005, 2, 106401, "シェフィ", "", 21, 0, 0, 428, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふんふ…はっ！？\nあっ、あんたたち！\nなに人の鼻歌を\n勝手に聞いてるのよ！？", 80005, 0, 106001, "キャル", "", 29, 0, 0, 429, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こっ、これは別に\nカルミナの曲じゃなくて…\nあたしのオリジナルソングよ！\n聞いたらお金取るわよっ！？", 80005, 0, 106001, "キャル", "", 30, 0, 0, 430, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えへへ、キャルちゃん\nカルミナのサマーライブ\n思いっきり楽しみましょうね☆", 80005, 3, 105801, "ペコリーヌ", "", 25, 0, 0, 431, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("も～っ！\n生暖かい目で見るな～～！\nぶっ殺すわよ～～～！", 80005, 0, 106001, "キャル", "", 31, 0, 0, 432, 0, 8);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと６日\n３人も言ってたけど\nあっという間だったわね", 80005, 0, 106401, "シェフィ", "", 22, 0, 0, 433, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…えっ？\n生放送の意気込み！？\n突然なに！？", 80005, 0, 106401, "シェフィ", "", 23, 0, 0, 434, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…\nとにかく失敗しないように\n台本たくさん読んで…\nそれから…", 80005, 0, 106401, "シェフィ", "", 24, 0, 0, 435, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ！？\nトラブルがあったら\nどうするのかって！？\nそ、それは…！", 80005, 0, 106401, "シェフィ", "", 25, 0, 0, 436, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("とにかく落ち着いて\nスタッフさんの指示を聞いて…", 80005, 0, 106401, "シェフィ", "", 26, 0, 0, 437, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それから、それから…！\nぅ、ぅぅっ…！", 80005, 0, 106401, "シェフィ", "", 27, 0, 0, 438, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("―びえぇぇ～んっ！！！", 80005, 0, 106401, "シェフィ", "", 28, 0, 0, 439, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("どうされましたか、シェフィさま", 80005, 1, 105901, "コッコロ", "", 20, 0, 0, 440, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ううっ…ひっく…\nママッ…！", 80005, 0, 106401, "シェフィ", "", 29, 0, 0, 441, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("よしよし、緊張されてるのですね\nママが傍におりますよ\n主さま、少々お待ちくださいませ", 80005, 1, 105901, "コッコロ", "", 21, 0, 0, 442, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ふぅ\nシェフィさま\n生放送への意気込み\nお話しできそうですか？", 80005, 1, 105901, "コッコロ", "", 22, 0, 0, 443, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ううっ\n恥ずかしすぎて\nもう生放送出られない…", 80005, 0, 106401, "シェフィ", "", 30, 0, 0, 444, 0, 9);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("主さま\n3.5周年まであと５日\nでございます", 80005, 0, 105901, "コッコロ", "", 23, 0, 0, 445, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですがその前に\n生放送がありますね", 80005, 0, 105901, "コッコロ", "", 24, 0, 0, 446, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…生放送に向けた\n意気込みでございますか？", 80005, 0, 105901, "コッコロ", "", 25, 0, 0, 447, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もちろんわたくしは\n主さまのために\n全身全霊を込めて\n楽しい時間をご提供いたします", 80005, 0, 105901, "コッコロ", "", 26, 0, 0, 448, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…と、意気込んでみましたが\nうまくできるか少し不安です\n声が小さくなったり\n間違えてしまったらどうしようと…", 80005, 0, 105901, "コッコロ", "", 27, 0, 0, 449, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですがわたくしは\n一人ではありません\n【美食殿】のみなさまが\nおります", 80005, 0, 105901, "コッコロ", "", 28, 0, 0, 450, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("どんな困難も\nみなさまと一緒なら\n乗り越えられると\nわたくし、確信しております", 80005, 0, 105901, "コッコロ", "", 29, 0, 0, 451, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それに今回はシェフィさまも\nご参加されるわけですし\nママとしてお手本に\nならねばなりませんね", 80005, 0, 105901, "コッコロ", "", 30, 0, 0, 452, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("主さま。3.5周年も\n食卓を囲んでいる時のような\n楽しい思い出を\n一緒に作りましょうね", 80005, 0, 105901, "コッコロ", "", 31, 0, 0, 453, 0, 10);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと４日！\nやばいですね☆", 80005, 0, 105801, "ペコリーヌ", "", 26, 0, 0, 454, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はいはい、やばいわね\nというかもうすぐ生放送だけど\nあんた準備はできてるの？", 80005, 1, 106001, "キャル", "", 32, 0, 0, 455, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ばっちりオイッスー☆　ですよ！\n『王家の装備』も全開です！", 80005, 0, 105801, "ペコリーヌ", "", 27, 0, 0, 456, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あとは前回を超える\n最高のオイッスー☆　を\nお届けできるように\n練習あるのみですかね！", 80005, 0, 105801, "ペコリーヌ", "", 28, 0, 0, 457, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルちゃんは\nどうなんですか？\nオイッスー☆　を\n毎日ちゃんと練習してますか？", 80005, 0, 105801, "ペコリーヌ", "", 29, 0, 0, 458, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はぁ！？　なんであたしまで\nその変なあいさつを練習しないと\nいけないのよ！", 80005, 1, 106001, "キャル", "", 33, 0, 0, 459, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もしかしてやってないんですか？\nダメですよキャルちゃん！\nシェフィちゃんだってちゃんと\n毎日練習してるのに！", 80005, 0, 105801, "ペコリーヌ", "", 30, 0, 0, 460, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こうなったらわたしがキャルちゃん\nにオイッスー☆　の『オ』から\nしっかり教えてあげないと！", 80005, 0, 105801, "ペコリーヌ", "", 31, 0, 0, 461, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆　の『オ』は\n口を大きく開いて〜\nドラゴンの骨つき肉に\nかぶりつく直前をイメージして〜", 80005, 0, 105801, "ペコリーヌ", "", 32, 0, 0, 462, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だからあたしはやるなんて一言も…", 80005, 1, 106001, "キャル", "", 34, 0, 0, 463, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", 80005, 0, 105801, "ペコリーヌ", "", 33, 0, 0, 464, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聞きなさいっての！！", 80005, 1, 106001, "キャル", "", 35, 0, 0, 465, 0, 11);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと３日…\nそして生放送は、明日…", 80005, 2, 106401, "シェフィ", "", 31, 0, 0, 466, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もっと台本を\n読み込んでおかないと…\nあと発声練習も…", 80005, 2, 106401, "シェフィ", "", 32, 0, 0, 467, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おいっす！\n…こうじゃなかったわね\nええと確か…", 80005, 2, 106401, "シェフィ", "", 33, 0, 0, 468, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("うう…あんなに練習したのに\nこれじゃみんなに迷惑かけちゃう…", 80005, 2, 106401, "シェフィ", "", 34, 0, 0, 469, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】の一員として\n認められるように\n頑張らないといけないのに\nよし、もう一度…", 80005, 2, 106401, "シェフィ", "", 35, 0, 0, 470, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("やってますねシェフィちゃん！", 80005, 3, 105801, "ペコリーヌ", "", 34, 0, 0, 471, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なによ、考えることは\nみんな同じってこと？", 80005, 0, 106001, "キャル", "", 36, 0, 0, 472, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。シェフィさま\nよろしければ\n仲間に入れてください\n一緒にやればきっとうまくできます", 80005, 1, 105901, "コッコロ", "", 32, 0, 0, 473, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("みんな…もちろんよ！", 80005, 2, 106401, "シェフィ", "", 36, 0, 0, 474, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それじゃ明日の生放送に向けて\n一緒に練習がんばりましょう☆", 80005, 3, 105801, "ペコリーヌ", "", 35, 0, 0, 475, 0, 12);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと２日と\n迫った本日は…\nいよいよ生放送です！", 80005, 2, 190801, "カリン", "", 7, 0, 0, 476, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】のみなさんが\n準備に入られていますので\nそれぞれ繋いでみましょう！\nまずはペコリーヌさんです！", 80005, 2, 190801, "カリン", "", 8, 0, 0, 477, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日もオイッスー☆\nみんなで一緒に\nオイッスー☆", 80005, 3, 105801, "ペコリーヌ", "", 36, 0, 0, 478, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お手本になるような\n発声練習ですね！\nそれでは続いてコッコロさん", 80005, 2, 190801, "カリン", "", 9, 0, 0, 479, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はじめちょろちょろ\nなかぱっぱ～♪\n生放送前にみなさまで\n食卓を囲んで英気を養いましょう", 80005, 4, 105901, "コッコロ", "", 33, 0, 0, 480, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さすが【美食殿】のママですね！\nそしてキャルさんは…", 80005, 2, 190801, "カリン", "", 10, 0, 0, 481, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫…大丈夫…\nあたしは大丈夫…", 80005, 1, 106001, "キャル", "", 37, 0, 0, 482, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("す、すごく震えてますけど\n大丈夫でしょうか…？\nそして今回初参加となる\n期待の新人シェフィさん！", 80005, 2, 190801, "カリン", "", 11, 0, 0, 483, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あうー？", 80005, 0, 106401, "シェフィ", "", 37, 0, 0, 484, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ…", 80005, 4, 105801, "みんな", "105901,34,106001,38,190801,12", 37, 1, 0, 485, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ちょ、ちょっとシェフィ！？\nなに赤ちゃん返りしてん―\nあ痛ぁっ！\n噛んだわこいつーっ！", 80005, 1, 106001, "キャル", "", 39, 0, 0, 486, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィさま\n緊張しすぎて\nしまったのでしょうね…\nおーよしよし…", 80005, 4, 105901, "コッコロ", "", 35, 0, 0, 487, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィちゃん！\nそういう時は手のひらに\n好きな文字を書いて\n食べちゃうといいですよ！", 80005, 3, 105801, "ペコリーヌ", "", 38, 0, 0, 488, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ええと、現場からは以上です！\n生放送はもうすぐ！\n特別なお知らせもありますので\nどうぞお楽しみに！", 80005, 2, 190801, "カリン", "", 13, 0, 0, 489, 0, 13);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年の記念日も\nいよいよ明日ね\n…って、あれ？", 80005, 2, 106401, "シェフィ", "", 38, 0, 0, 490, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("記念日はこの森へ行きませんか！？\nすっごく美味しいお肉が\nとれるんです☆", 80005, 3, 105801, "ペコリーヌ", "", 39, 0, 0, 491, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("うげ、またあの魔物？\nさすがに今度は\n丸焼きとかはやめてよね…\n見た目がヤバすぎるし", 80005, 0, 106001, "キャル", "", 40, 0, 0, 492, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ、キャルさまもだいぶ\n魔物肉に慣れてきたようですね\n調理ならばわたくしに\nお任せください♪", 80005, 1, 105901, "コッコロ", "", 36, 0, 0, 493, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("みんな、何をしているの？\nなんだか、\n不穏な単語が聞こえたんだけど…", 80005, 2, 106401, "シェフィ", "", 39, 0, 0, 494, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィちゃん！\n明日の食べ尽くしツアーの\n相談をしてたんですよ！", 80005, 3, 105801, "ペコリーヌ", "", 40, 0, 0, 495, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。明日は【美食殿】の\n一員となったシェフィさまと一緒に\n初めて記念日を過ごすのですから\n特別なコース料理を用意しませんと", 80005, 1, 105901, "コッコロ", "", 37, 0, 0, 496, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふん♪\n猫の毛も逆立つような\nあれこれを食べさせられるから\n覚悟しておいたほうがいいわよ？", 80005, 0, 106001, "キャル", "", 41, 0, 0, 497, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("へ、へぇ…", 80005, 2, 106401, "シェフィ", "", 40, 0, 0, 498, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("期待しててくださいね！\nシェフィちゃんとあなたに\n『おいちー！』って喜んでもらえる\n最高のごちそうを準備しますから☆", 80005, 3, 105801, "ペコリーヌ", "", 41, 0, 0, 499, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…その…うーんと…\nわ、分かったわ\n私も【美食殿】の一員だもの", 80005, 2, 106401, "シェフィ", "", 41, 0, 0, 500, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それにあなたも一緒みたいだし\n最後までがんばってみるわ…！", 80005, 2, 106401, "シェフィ", "", 42, 0, 0, 501, 0, 14);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それではいつものあれを\nやりましょう！\n準備はいいですかっ？\n…いっきますよー！", 80005, 3, 105801, "ペコリーヌ", "", 42, 0, 0, 502, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("祝！", 80005, 1, 106001, "キャル", "", 42, 0, 0, 503, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年！", 80005, 4, 105901, "コッコロ", "", 38, 0, 0, 504, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おめでとうございます！", 80005, 0, 106401, "シェフィ", "", 43, 0, 0, 505, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この日を迎えられたのも\nあなたが『プリンセスコネクト！\nRe:Dive』を遊んでくれている\nおかげです！", 80005, 2, 190801, "カリン", "", 14, 0, 0, 506, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ということで\nみなさんからあなたへ一言ずつ\n感謝の言葉をどうぞ！", 80005, 2, 190801, "カリン", "", 15, 0, 0, 507, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("感謝の言葉ですか？　わたしは\n毎日あなたに感謝してますよ\n【美食殿】の仲間になってくれて…\n一緒にごはんを食べてくれて…", 80005, 3, 105801, "ペコリーヌ", "", 43, 0, 0, 508, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なにより今でもわたしをぺコリーヌ\nって呼んでくれてありがとうござい\nます。これからもわたしはあなたの\nぺコリーヌです！　やばいですね☆", 80005, 3, 105801, "ペコリーヌ", "", 44, 0, 0, 509, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ！？　今度はあたし！？\n感謝って…まぁ、そうね…\nあんたにはあたしが\n辛くて苦しい時に助けてもらって…", 80005, 1, 106001, "キャル", "", 43, 0, 0, 510, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("でもおかげで色々吹っ切れたわ！\nもしあんたが困ってたら今度は\nあたしが助けてあげるから\nその時はちゃんと言いなさいよ！", 80005, 1, 106001, "キャル", "", 44, 0, 0, 511, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…次は私ね\n実はよく覚えてないのだけど\n空から落ちてきた私を受け止めて\nくれたのはあなたなのでしょう？", 80005, 0, 106401, "シェフィ", "", 44, 0, 0, 512, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("最初に私を見つけてくれたのが\nあなたで良かったって思ってるの\nおかげで私は居場所を見つけたから\nあなたがくれたもの、大切にするわ", 80005, 0, 106401, "シェフィ", "", 45, 0, 0, 513, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("では最後にわたくしから…\nわたくしは主さまの元を離れた日…\nこのように記念日をお祝いする\nことは二度とないと思っていました", 80005, 4, 105901, "コッコロ", "", 39, 0, 0, 514, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですが、主さまはわたくしを\n迎えにきてくださり、今もこうして\nおそばにおいてくださっています\nわたくしにとって毎日が記念日です", 80005, 4, 105901, "コッコロ", "", 40, 0, 0, 515, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくしたちの物語は\nまだ続いていきます\nこれからも一緒にページを\n作っていきましょうね", 80005, 4, 105901, "コッコロ", "", 41, 0, 0, 516, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それじゃ\nいつものあれでしめますよ！\nみんなで一緒に、さんはい☆", 80005, 3, 105801, "ペコリーヌ", "", 45, 0, 0, 517, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも\nよろしくおねがいします！", 80005, 4, 105801, "みんな", "105901,42,106001,45,106401,46,190801,16", 46, 1, 0, 518, 0, 15);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 60003, 1, 190804, "カリン", "", 1, 0, 0, 519, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", 60003, 2, 0, "", "", 0, 0, 1, 520, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", 60003, 2, 0, "", "", 0, 0, 1, 521, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", 60003, 2, 0, "", "", 0, 0, 1, 522, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　精霊も新年の幸福をお祝いしています！　　主さまの笑顔が見られて、わたくしも幸せいっぱいでございます♪", 60003, 2, 0, "", "", 0, 0, 1, 523, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", 60003, 2, 0, "", "", 0, 0, 1, 524, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 60003, 2, 0, "", "", 0, 0, 2, 525, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", 60003, 2, 0, "", "", 0, 0, 2, 526, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーカラーは鮮やかな黄色！　　　　　さらにシマシマのアイテムを持つと、運気倍増らしいッスよ♪", 60003, 2, 0, "", "", 0, 0, 2, 527, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", 60003, 2, 0, "", "", 0, 0, 2, 528, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", 60003, 2, 0, "", "", 0, 0, 2, 529, 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", 60003, 2, 0, "", "", 0, 0, 3, 530, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", 60003, 2, 0, "", "", 0, 0, 3, 531, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", 60003, 2, 0, "", "", 0, 0, 3, 532, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", 60003, 2, 0, "", "", 0, 0, 3, 533, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", 60003, 2, 0, "", "", 0, 0, 3, 534, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", 60003, 2, 0, "", "", 0, 0, 3, 535, 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", 60003, 2, 0, "", "", 0, 0, 3, 536, 2, 0);
